// A developer's day: makes the next change from the list below, a real dependency added at an old release with code
// that uses it and a test (or code that calls a provider's API), as a person working from an old example would.
// Darwin should then find the newer release and propose it (migrating the code when it breaks), hold it with the
// reason, or fix the call to what the provider retired. The code is kept base64-encoded here so that no scan of the
// repository finds it before the developer "writes" it.
//
//   node .github/fixture/developer.mjs -> writes the files; prints {"packages","devPackages","message"}, or {} when the
//                                         list is done. The workflow installs the packages, type-checks, tests, commits.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname } from 'node:path'

const CHANGES = JSON.parse(Buffer.from('', 'base64').toString('utf8'))

const LOG = '.github/fixture/developer-log.json'
const done = existsSync(LOG) ? JSON.parse(readFileSync(LOG, 'utf8')) : []
const index = CHANGES.findIndex((_, i) => !done.includes(i))
if (index === -1) {
  process.stdout.write('{}')
  process.exit(0)
}
const change = CHANGES[index]
for (const [path, content] of Object.entries(change.files)) {
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, Buffer.from(content, 'base64'))
}
writeFileSync(LOG, JSON.stringify([...done, index]) + '\n')
const subject = change.subject ?? `fixture: add dependency ${change.module} ${change.version}`
const message = [subject, '', change.note, '', ...change.fields].join('\n')
process.stdout.write(JSON.stringify({ packages: change.packages, devPackages: change.devPackages ?? [], message }))
